 public sealed partial class Controller {
 bool appearanceReady;string previewBackground="",releaseUrl;int settingTab;
 double Number(string key,double value,double min,double max){double x;return Double.TryParse(db.Get(key,value.ToString(CultureInfo.InvariantCulture)),NumberStyles.Float,CultureInfo.InvariantCulture,out x)&&!Double.IsNaN(x)&&!Double.IsInfinity(x)?Math.Max(min,Math.Min(max,x)):value;}
 void SetupModern(){Chrome.Radius=Number("cornerRadius",16,0,32);Chrome.Decorate(w,true);Get<Border>("WindowSurface").CornerRadius=new CornerRadius(Chrome.Radius);Get<Image>("AboutIcon").Source=AppIdentity.BrandImage;
 Get<ComboBox>("ThemeInput").SelectedIndex=(int)Number("theme",0,0,2);Get<ComboBox>("AccentInput").SelectedIndex=(int)Number("accent",0,0,5);Get<Slider>("RadiusInput").Value=Chrome.Radius;Get<Slider>("BackgroundOpacity").Value=Number("backgroundOpacity",.25,0,.65);Get<Slider>("BackgroundBlur").Value=Number("backgroundBlur",12,0,40);Get<TextBox>("BackgroundPath").Text=db.Get("backgroundPath","");
 Get<CheckBox>("AutoStartInput").IsChecked=demo?Setting("autoStart",false):StartupManager.Enabled;Get<CheckBox>("RunAsAdminInput").IsChecked=demo?Setting("runAsAdmin",true):StartupManager.PreferAdmin;
 Click("MinimizeWindow",delegate{w.WindowState=WindowState.Minimized;});Click("MaximizeWindow",delegate{w.WindowState=w.WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;});Click("CloseWindow",delegate{w.Close();});
 w.StateChanged+=delegate{Get<System.Windows.Shapes.Path>("MaximizeGlyph").Data=Geometry.Parse(w.WindowState==WindowState.Maximized?"M3,1 H11 V9 M1,3 H9 V11 H1 Z":"M1,1 H11 V11 H1 Z");};
 Get<Grid>("TitleBar").MouseLeftButtonDown+=delegate(object sender,MouseButtonEventArgs e){if(e.ClickCount==2){w.WindowState=w.WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;return;}try{w.DragMove();}catch{}};
 string[] tabs={"Appearance","General","Hidden","Hotkeys","Data"};for(int i=0;i<tabs.Length;i++){int n=i;Click("Settings"+tabs[i],delegate{SelectSettings(n);});}
 Click("NavAbout",delegate{Navigate(3);});Click("OpenProjectButton",delegate{OpenUrl(UpdateService.ProjectUrl);});Click("OpenReleaseButton",delegate{if(releaseUrl!=null)OpenUrl(releaseUrl);});Click("CheckUpdateButton",CheckUpdates);Click("OpenDataButton",delegate{System.Diagnostics.Process.Start("explorer.exe","\""+Path.GetDirectoryName(db.FilePath)+"\"");});
 Click("ChooseBackgroundButton",delegate{var dialog=new Microsoft.Win32.OpenFileDialog{Filter="图片 (*.png;*.jpg;*.jpeg;*.bmp)|*.png;*.jpg;*.jpeg;*.bmp",CheckFileExists=true};if(dialog.ShowDialog(w)==true){try{LoadBackground(dialog.FileName);Get<TextBox>("BackgroundPath").Text=dialog.FileName;}catch(Exception ex){Error(ex);}}});Click("ClearBackgroundButton",delegate{Get<TextBox>("BackgroundPath").Text="";PreviewAppearance();});
 Get<ComboBox>("ThemeInput").SelectionChanged+=delegate{PreviewAppearance();};Get<ComboBox>("AccentInput").SelectionChanged+=delegate{PreviewAppearance();};foreach(string n in new[]{"RadiusInput","BackgroundOpacity","BackgroundBlur"})Get<Slider>(n).ValueChanged+=delegate{PreviewAppearance();};
 Microsoft.Win32.SystemEvents.UserPreferenceChanged+=SystemThemeChanged;w.Closed+=delegate{Microsoft.Win32.SystemEvents.UserPreferenceChanged-=SystemThemeChanged;};Get<Grid>("ShellGrid").SizeChanged+=delegate{ClipBackground();};appearanceReady=true;PreviewAppearance();SelectSettings(0);
 }
 void ClipBackground(){var shell=Get<Grid>("ShellGrid");shell.Clip=new RectangleGeometry(new Rect(0,0,Math.Max(0,shell.ActualWidth),Math.Max(0,shell.ActualHeight)),Chrome.Radius,Chrome.Radius);}
 void SystemThemeChanged(object sender,Microsoft.Win32.UserPreferenceChangedEventArgs e){w.Dispatcher.BeginInvoke(new Action(delegate{if(Get<ComboBox>("ThemeInput").SelectedIndex==2)PreviewAppearance();}));}
 void SelectSettings(int n){settingTab=n;string[] tabs={"Appearance","General","Hidden","Hotkeys","Data"};for(int i=0;i<tabs.Length;i++){Get<StackPanel>(tabs[i]+"Section").Visibility=n==i?Visibility.Visible:Visibility.Collapsed;var button=Get<Button>("Settings"+tabs[i]);if(n==i)button.SetResourceReference(Control.BackgroundProperty,"AccentSoft");else button.Background=Brushes.Transparent;button.SetResourceReference(Control.ForegroundProperty,n==i?"Accent":"Muted");}Get<ScrollViewer>("SettingsPanel").ScrollToTop();}
 void PreviewAppearance(){if(!appearanceReady)return;ThemeManager.Apply(w,Get<ComboBox>("ThemeInput").SelectedIndex.ToString(),Get<ComboBox>("AccentInput").SelectedIndex);double radius=Get<Slider>("RadiusInput").Value;Chrome.Radius=radius;Get<Border>("WindowSurface").CornerRadius=new CornerRadius(radius);Chrome.Round(w,radius);ClipBackground();PaintNavigation();var image=Get<Image>("BackgroundImage");image.Opacity=Get<Slider>("BackgroundOpacity").Value;((BlurEffect)image.Effect).Radius=Get<Slider>("BackgroundBlur").Value;Text("RadiusLabel",radius.ToString("0")+" px");Text("OpacityLabel",image.Opacity.ToString("P0"));Text("BlurLabel",((BlurEffect)image.Effect).Radius.ToString("0")+" px");string path=Get<TextBox>("BackgroundPath").Text;if(path!=previewBackground)try{LoadBackground(path);}catch(Exception ex){Status("背景图片不可用："+ex.Message);}PaintNavigation();}
 internal void LoadBackground(string path){var image=Get<Image>("BackgroundImage");if(String.IsNullOrWhiteSpace(path)){image.Source=null;previewBackground="";return;}if(!File.Exists(path))throw new FileNotFoundException("图片已移动或删除");if(new FileInfo(path).Length>40*1024*1024)throw new IOException("请选择小于 40 MB 的背景图片");var bitmap=new BitmapImage();using(var stream=File.OpenRead(path)){bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.DecodePixelWidth=1920;bitmap.StreamSource=stream;bitmap.EndInit();bitmap.Freeze();}image.Source=bitmap;previewBackground=path;}
 void SaveModern(){LoadBackground(Get<TextBox>("BackgroundPath").Text);db.Set("autoStart",Get<CheckBox>("AutoStartInput").IsChecked==true?"1":"0");db.Set("runAsAdmin",Get<CheckBox>("RunAsAdminInput").IsChecked==true?"1":"0");db.Set("theme",Get<ComboBox>("ThemeInput").SelectedIndex.ToString());db.Set("accent",Get<ComboBox>("AccentInput").SelectedIndex.ToString());foreach(var pair in new[]{new[]{"cornerRadius","RadiusInput"},new[]{"backgroundOpacity","BackgroundOpacity"},new[]{"backgroundBlur","BackgroundBlur"}})db.Set(pair[0],Get<Slider>(pair[1]).Value.ToString(CultureInfo.InvariantCulture));db.Set("backgroundPath",Get<TextBox>("BackgroundPath").Text);if(!demo)StartupManager.Apply(Get<CheckBox>("AutoStartInput").IsChecked==true,Get<CheckBox>("RunAsAdminInput").IsChecked==true);}
 void PaintNavigation(){string[] names={"NavCurrent","NavRestore","NavSettings","NavAbout"};for(int i=0;i<names.Length;i++){var b=Get<Button>(names[i]);b.SetResourceReference(Control.ForegroundProperty,i==page?"Accent":"Muted");if(i==page)b.SetResourceReference(Control.BackgroundProperty,"AccentSoft");else b.Background=Brushes.Transparent;}}
 void OpenUrl(string url){System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(url){UseShellExecute=true});}
  async void CheckUpdates(){var button=Get<Button>("CheckUpdateButton");button.IsEnabled=false;Text("UpdateStatus","正在检查 GitHub 正式发布…");Get<Button>("OpenReleaseButton").Visibility=Visibility.Collapsed;try{string tag=await UpdateService.Latest();if(UpdateService.IsNewer(tag,"0.8.8")){releaseUrl=UpdateService.ProjectUrl+"/releases/tag/"+Uri.EscapeDataString(tag);Text("UpdateStatus","发现新版本 "+tag+"，可前往发布页查看更新");Get<Button>("OpenReleaseButton").Visibility=Visibility.Visible;}else Text("UpdateStatus","当前已是最新版本 v0.8.8");}catch(WebException ex){var response=ex.Response as HttpWebResponse;Text("UpdateStatus",response!=null&&response.StatusCode==HttpStatusCode.NotFound?"尚无可用的公开正式发布，请稍后重试":"检查失败，请确认网络连接或稍后重试");}catch(Exception ex){Text("UpdateStatus","检查失败："+ex.Message);}finally{button.IsEnabled=true;}}
 }
